create or replace function public.listing_offers_animals(title text, description text)
returns boolean
language plpgsql
immutable
set search_path = public
as $fn$
declare
    combined text;
    about_accessory boolean;
begin
    combined := ' ' || trim(regexp_replace(
        translate(lower(coalesce(title, '') || ' ' || coalesce(description, '')),
                  'àáâäãåèéêëìíîïòóôöõùúûüñç', 'aaaaaaeeeeiiiiooooouuuunc'),
        '[^a-z0-9]+', ' ', 'g')) || ' ';
    about_accessory := combined ~ '\m(?:transporttasche|abbigliamento|illuminazione|transportines|abbeveratoio|impermeabile|riscaldatore|transportbox|accessoires|accessories|croccantini|integratore|kinderwagen|transportin|trasportini|trasportino|accesorios|accessoire|accessorio|calentador|cappottini|cappottino|couverture|crocchette|croquettes|fontanella|friandises|futternapf|guinzaglio|halsbander|katzenbett|mangiatoia|medicinale|nourriture|passeggino|scratching|tiragraffi|accesorio|accessori|accessory|antipulci|bardatura|chauffage|cochecito|fressnapf|golosinas|guinzagli|hundebett|katzenklo|kratzbaum|museliere|muselière|museruola|museruole|pettorina|pettorine|poussette|scratcher|shampoing|spielzeug|tappetino|terrarium|vestitino|vetements|acquario|aquarium|backpack|bebedero|biscotti|cappotto|carriers|clothing|collares|colliers|comedero|cuccetta|geschirr|griffoir|halsband|juguetes|kleidung|leckerli|lettiera|lettiere|maglione|mantella|maulkorb|pullover|raincoat|rascador|rucksack|scaletta|spazzola|spazzole|striscia|stroller|terrario|training|truciolo|vetement|vivarium|acquari|acuario|arenero|blanket|carrier|casetta|cepillo|cestino|ciotola|ciotole|clothes|collare|collari|collars|collier|coussin|cuscini|cuscino|cushion|gamelle|harnais|harness|heizung|juguete|knochen|lettino|litiere|manteau|mochila|pallina|palline|paniers|playpen|recinti|recinto|scatola|scratch|sellino|shampoo|sweater|vestito|voliera|voliere|zubehor|abrigo|bridle|brosse|burste|caisse|canile|caseta|champu|collar|comida|correa|crates|cuccia|enclos|feeder|filter|filtre|filtro|futter|gabbia|gabbie|gehege|giochi|heater|jacket|jaulas|jouets|jumper|kennel|kissen|laisse|litter|mantel|muzzle|panier|parque|pelota|pienso|saddle|sattel|stairs|tasche|treats|treppe|arnes|balle|bolso|bomba|borsa|bowls|bozal|brush|cages|camas|cesta|cesto|cojin|cover|crate|cucce|decke|felpa|fieno|gioco|house|hueso|hutte|imper|jaula|jouet|kafig|leash|leine|manta|niche|pompa|pompe|pumpe|rampa|rampe|sella|selle|silla|snack|streu|zaino|ball|beds|bett|bone|bowl|cage|cama|cibo|coat|foin|food|heno|korb|lamp|lead|napf|ossa|osso|pads|pump|ramp|ropa|tank|tira|toys|tree|bag|bed|box|hay|heu|mat|pad|pen|sac|toy|os)\M';
    return public.listing_text_offers_animals(title, about_accessory)
        or public.listing_text_offers_animals(description, about_accessory);
end;
$fn$;

revoke all on function public.listing_text_offers_animals(text, boolean)
    from public, anon, authenticated;
revoke all on function public.listing_offers_animals(text, text)
    from public, anon, authenticated;

-- Un utente normale non deve poter riattivare un annuncio nascosto: la guardia
-- del database tratta 'removed_policy' come 'removed' (stessa funzione di
-- supabase_schema.sql).
create or replace function public.guard_marketplace_listing()
returns trigger
language plpgsql
set search_path = public
as $$
begin
    new.latitude := round(new.latitude::numeric, 2)::double precision;
    new.longitude := round(new.longitude::numeric, 2)::double precision;

    if current_user in ('authenticated', 'anon') then
        if tg_op = 'INSERT' then
            new.report_count := 0;
            new.status := 'active';
        else
            new.owner_id := old.owner_id;
            new.created_at := old.created_at;
            new.report_count := old.report_count;
            if old.status in ('removed', 'removed_policy')
               or new.status in ('removed', 'removed_policy') then
                new.status := old.status;
            end if;
        end if;
    end if;

    return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- PARTE A - ANTEPRIMA (non modifica nulla)
-- ---------------------------------------------------------------------------
select count(*) as annunci_da_nascondere
from public.marketplace_listings
where status in ('active', 'reserved')
  and public.listing_offers_animals(title, description);

select id, title, left(coalesce(description, ''), 80) as description, country, created_at
from public.marketplace_listings
where status in ('active', 'reserved')
  and public.listing_offers_animals(title, description)
order by created_at desc
limit 50;

-- ---------------------------------------------------------------------------
-- PARTE B - NASCONDE GLI ANNUNCI (eseguire solo dopo aver guardato la parte A)
-- ---------------------------------------------------------------------------
update public.marketplace_listings
set status = 'removed_policy',
    updated_at = now()
where status in ('active', 'reserved')
  and public.listing_offers_animals(title, description);
